begin;
create or replace function public.listar_estoque(p_oficina uuid,p_busca text default '',p_filtro text default '',p_pagina integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$
declare lista jsonb; total bigint; resumo jsonb;begin
 perform private.exigir_estoque(p_oficina);
 select jsonb_build_object('produtos',count(*),'baixos',count(*) filter(where e.saldo<=e.minimo),'zerados',count(*) filter(where e.saldo=0),'valor_centavos',coalesce(sum(round(e.saldo*e.custo_centavos)),0)) into resumo from public.estoque_produtos e join public.itens_catalogo c on c.id=e.item_catalogo_id and c.oficina_id=e.oficina_id where e.oficina_id=p_oficina and c.arquivado_em is null;
 select count(*) into total from public.itens_catalogo c left join public.estoque_produtos e on e.item_catalogo_id=c.id and e.oficina_id=c.oficina_id where c.oficina_id=p_oficina and c.tipo='part' and ((p_filtro='arquivados' and c.arquivado_em is not null) or (p_filtro<>'arquivados' and c.arquivado_em is null)) and (p_filtro<>'baixo' or e.saldo<=e.minimo) and (p_filtro<>'zerado' or e.saldo=0) and concat(c.descricao,' ',e.codigo) ilike '%'||left(p_busca,120)||'%';
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into lista from (select c.id,c.descricao,c.unidade,c.preco_padrao_centavos,c.arquivado_em,e.codigo,e.localizacao,e.fornecedor,e.saldo,e.minimo,e.custo_centavos,e.revisao from public.itens_catalogo c left join public.estoque_produtos e on e.item_catalogo_id=c.id and e.oficina_id=c.oficina_id where c.oficina_id=p_oficina and c.tipo='part' and ((p_filtro='arquivados' and c.arquivado_em is not null) or (p_filtro<>'arquivados' and c.arquivado_em is null)) and (p_filtro<>'baixo' or e.saldo<=e.minimo) and (p_filtro<>'zerado' or e.saldo=0) and concat(c.descricao,' ',e.codigo) ilike '%'||left(p_busca,120)||'%' order by c.descricao,c.id limit 24 offset greatest(p_pagina,0)*24) x;
 return jsonb_build_object('itens',lista,'total',total,'resumo',resumo);end $$;
commit;
